/bin/bash -lc ".venv/bin/python - <<'PY'
from pathlib import Path
import json, re, xml.etree.ElementTree as ET
from server.core import render_svg, render_drawio
root=Path('.')
name='fig01_evidence_synthesis_map'
notes=(root/'workspace/notes/figure_parts/fig01.md').read_text(encoding='utf-8')
allowed=[]
in_whitelist=False
for line in notes.splitlines():
    if line.startswith('### A6. 可见文字白名单'):
        in_whitelist=True
        continue
    if in_whitelist and line.startswith('### '):
        break
    m=re.match(r'"'^'"\\d+\\. "'`(.+)`$'"', line)
    if in_whitelist and m:
        allowed.append(m.group(1))
norm=lambda s: s.replace('\\n','')
allowed_norm={norm(s) for s in allowed}
spec_path=root/f'workspace/figures/figspec/{name}.json'
svg_path=root/f'workspace/figures/svg/{name}.svg'
drawio_path=root/f'workspace/figures/drawio/{name}.drawio'
spec=json.loads(spec_path.read_text(encoding='utf-8'))
visible=[]
if spec.get('title'): visible.append(('title',spec['title']))
for g in spec.get('groups',[]):
    if g.get('label'): visible.append((f\"group:{g['id']}\",g['label']))
for n in spec.get('nodes',[]):
    for key in ('label','sublabel'):
        if n.get(key): visible.append((f\"node:{n['id']}:{key}\",n[key]))
for e in spec.get('edges',[]):
    if e.get('label'): visible.append((f\"edge:{e['id']}\",e['label']))
for t in spec.get('texts',[]):
    if t.get('text'): visible.append((f\"text:{t['id']}\",t['text']))
viol=[(where,text) for where,text in visible if norm(text) not in allowed_norm]
ET.parse(svg_path)
ET.parse(drawio_path)
svg_same=svg_path.read_text(encoding='utf-8') == render_svg.render(spec)
drawio_same=drawio_path.read_text(encoding='utf-8') == render_drawio.render(spec,page_name=name)
print(json.dumps({
  'whitelist_entries':len(allowed),
  'visible_items':len(visible),
  'whitelist_violations':viol,
  'svg_xml':'ok','drawio_xml':'ok',
  'svg_matches_figspec':svg_same,
  'drawio_matches_figspec':drawio_same,
  'sizes':{str(p):p.stat().st_size for p in (spec_path,svg_path,drawio_path)},
  'edge_map':{e['id']:[e['from'],e['to'],bool(e.get('dashed')),e.get('label','')] for e in spec['edges']}
},ensure_ascii=False,indent=2))
PY"

